const length = (segments: Segment[]) => segments.reduce((sum,s) => sum+Math.hypot(...s.to.map((v,i) => v-s.from[i])),0);
function covered(a: Segment[], b: Segment[], tolerance: number) {
  return a.every(s => Array.from({length:21},(_,i) => s.from.map((v,j) => v+(s.to[j]-v)*i/20) as Vec).every(p => b.some(t => distance(p,t) <= tolerance)));
}
export function checkChallenge(challenge: Challenge, result: Result): { passed: boolean; message: string } {
  if (result.error) return {passed:false,message:"'`Najpierw popraw program: ${result.error.message} (wiersz ${result.error.line}).`};
  if (!result.segments.length) return {passed:false,message:'"'Jeszcze nie ma rysunku. Opuść pióro i zrób pierwszy krok.'};
  const expected = run(challenge.target,challenge.mode).segments;
  const expectedLength = length(expected), actualLength = length(result.segments);
  if ("'!covered(result.segments,expected,1.2)) return {passed:false,message:'"'Część linii jest poza wzorem. Sprawdź długości, kąty i położenie początku rysunku.'};
  if ("'!covered(expected,result.segments,1.2)) return {passed:false,message:'"'Brakuje części wzoru. Sprawdź liczbę boków lub powtórzeń i czy pióro jest opuszczone.'};
  if (Math.abs(expectedLength-actualLength) > expectedLength*0.025) return {passed:false,message:'Kształt pasuje, ale długość wszystkich kresek się różni. Czy nie rysujesz któregoś odcinka drugi raz?'};
  return {passed:true,message:'Udało się"'! Wszystkie linie pasują do wzoru. Kolejny krok należy do Ciebie.'"'};
