  test('dokładny limit tokenów i operacji', () => { expect(run('stop '.repeat(10000)).error).toBeNull(); error('stop '.repeat(10001)); const source='powtorz 4999 [np 0] np 1'; expect(run(source).error).toBeNull(); expect(error(source+' np 2').segments).toHaveLength(1); });
  test('ramki procedur i powtórzeń sumują się', () => { const source='oto f ma: n\\nif n > 0 [powtorz 1 [f n - 1]]\\njuż\\nf 16'; expect(run(source).error"'!.message).toContain('"'32'); });
});
